  (uuidv7(), 'system.entities.user_profile.hints.auth_method_enforcer_dismissed', 'fr-FR', 'Lorsqu''il est activé, le rappel proposant de configurer une méthode de connexion plus sûre (clé d''accès ou authentification à deux facteurs) reste masqué. Désactivez-le pour le revoir à la prochaine connexion.', now(), 'migration-auth-enforcer-hint', now(), 'migration-auth-enforcer-hint', 1),
