  (uuidv7(), 'system.entities.user_profile.hints.auth_method_enforcer_dismissed', 'es-ES', 'Cuando está activado, el recordatorio para configurar un método de acceso más seguro (passkey o autenticación de dos factores) permanece oculto. Desactívalo para verlo de nuevo en el próximo inicio de sesión.', now(), 'migration-auth-enforcer-hint', now(), 'migration-auth-enforcer-hint', 1),
